import unittest

class TestCases(unittest.TestCase):
    def test_simple(self):
        self.assertEqual(task_func([{'name': 'a', 'amount': 3}, {'name': 'b', 'amount': 5}]), 'b')
    def test_tie(self):
        self.assertEqual(task_func([{'name': 'b', 'amount': 5}, {'name': 'a', 'amount': 5}]), 'a')
    def test_empty(self):
        self.assertIsNone(task_func([]))
    def test_accumulate(self):
        self.assertEqual(task_func([{'name': 'a', 'amount': 3}, {'name': 'a', 'amount': 4}, {'name': 'b', 'amount': 5}]), 'a')

