def task_func(rows):
    totals = {}
    for r in rows:
        totals[r['name']] = totals.get(r['name'], 0) + r['amount']
    if not totals:
        return None
    return sorted(totals.items(), key=lambda kv: (-kv[1], kv[0]))[0][0]
